#!/usr/bin/env node
// Generates typed ABI + deployment constants for the web app from Foundry artifacts and the
// deployment manifest (the source of truth for deployed addresses).
//
//   node contracts/script/export-abi.mjs                  forge build, then (re)write lib/chain/generated/
//   node contracts/script/export-abi.mjs --check          write nothing; exit 1 if generated files are stale
//   node contracts/script/export-abi.mjs --no-build       skip `forge build` (use existing contracts/out)
//   node contracts/script/export-abi.mjs --verify-onchain compare deployed bytecode to the artifacts
//                                                         (read-only; needs XRPL_EVM_RPC_URL in the env,
//                                                         e.g. `set -a; source .env; set +a`; never printed)
//
// Requires Foundry (`forge`, `cast`) and the repo's dev dependencies (prettier).
import { execFileSync } from "node:child_process"
import { createHash } from "node:crypto"
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs"
import { dirname, join, relative, resolve } from "node:path"
import { fileURLToPath } from "node:url"
import * as prettier from "prettier"

const args = new Set(process.argv.slice(2))
const KNOWN = new Set(["--check", "--no-build", "--verify-onchain"])
for (const a of args) {
  if (!KNOWN.has(a)) fail(`unknown flag ${a}`)
}
const CHECK = args.has("--check")

const contractsDir = resolve(dirname(fileURLToPath(import.meta.url)), "..")
const repoRoot = resolve(contractsDir, "..")
const outDir = join(repoRoot, "lib", "chain", "generated")
const manifestPath = join(contractsDir, "deployments", "xrpl-evm-testnet.json")

const EXPECTED_CHAIN_ID = 1449000

// Public ABI surface frozen by docs/CONTRACT_SPEC.md v1.1 §5-§7.
const SPEC = {
  functions: [
    "createInvoice",
    "cancelInvoice",
    "fundInvoice",
    "depositReserve",
    "withdrawReserve",
    "approveAdvance",
    "approveCompletion",
    "raiseDispute",
    "resolveDispute",
    "getInvoice",
    "availableReserve",
  ],
  events: [
    "InvoiceCreated",
    "InvoiceFunded",
    "InvoiceCancelled",
    "ReserveDeposited",
    "ReserveWithdrawn",
    "AdvancePaid",
    "InvoiceSettled",
    "InvoiceDisputed",
    "DisputeResolved",
  ],
  errors: [
    "InvoiceNotFound",
    "InvalidAddress",
    "InvalidAmount",
    "InvalidHash",
    "InvalidInvoiceParties",
    "InvalidStatus",
    "NotInvoiceClient",
    "NotInvoiceFreelancer",
    "InsufficientReserve",
    "ZeroAdvance",
    "UnsupportedTokenBehavior",
  ],
}

function fail(msg) {
  console.error(`export-abi: ${msg}`)
  process.exit(1)
}

function run(cmd, cmdArgs, opts = {}) {
  try {
    return execFileSync(cmd, cmdArgs, { encoding: "utf8", ...opts }).trim()
  } catch (e) {
    fail(`\`${cmd} ${cmdArgs[0] ?? ""}\` failed: ${String(e.stderr || e.message).split("\n")[0]}`)
  }
}

function checksum(address) {
  return run("cast", ["to-check-sum-address", address])
}

function isAddress(a) {
  return typeof a === "string" && /^0x[0-9a-fA-F]{40}$/.test(a)
}

function loadArtifact(name) {
  const p = join(contractsDir, "out", `${name}.sol`, `${name}.json`)
  if (!existsSync(p)) fail(`missing artifact ${relative(repoRoot, p)}; run \`forge build\``)
  return { path: p, json: JSON.parse(readFileSync(p, "utf8")) }
}

function names(abi, type) {
  return abi.filter((x) => x.type === type).map((x) => x.name)
}

function assertSpec(abi) {
  for (const [kind, type] of [
    ["functions", "function"],
    ["events", "event"],
    ["errors", "error"],
  ]) {
    const have = new Set(names(abi, type))
    const missing = SPEC[kind].filter((n) => !have.has(n))
    if (missing.length) fail(`InvoiceAdvance ABI is missing spec ${kind}: ${missing.join(", ")}`)
  }
}

async function format(source) {
  return prettier.format(source, {
    parser: "typescript",
    semi: false,
    singleQuote: false,
    tabWidth: 2,
    trailingComma: "es5",
    printWidth: 80,
    endOfLine: "lf",
  })
}

const HEADER = (what, from) =>
  `// AUTO-GENERATED by contracts/script/export-abi.mjs - DO NOT EDIT.\n` +
  `// ${what}\n// Source: ${from}\n// Regenerate: node contracts/script/export-abi.mjs\n\n`

// ---- 1. build + load ----------------------------------------------------------------------

if (!args.has("--no-build")) {
  run("forge", ["build"], { cwd: contractsDir })
}

const manifest = JSON.parse(readFileSync(manifestPath, "utf8"))
const ia = loadArtifact("InvoiceAdvance")
const token = loadArtifact("MockUSDC")
assertSpec(ia.json.abi)

// ---- 2. validate the manifest -------------------------------------------------------------

if (manifest.chainId !== EXPECTED_CHAIN_ID) fail(`manifest chainId ${manifest.chainId} != ${EXPECTED_CHAIN_ID}`)
const tokenAddr = manifest.paymentToken?.address
const iaAddr = manifest.invoiceAdvance?.address
if (!isAddress(tokenAddr) || !isAddress(iaAddr)) fail("manifest contract addresses are invalid")
if (manifest.invoiceAdvance.paymentToken.toLowerCase() !== tokenAddr.toLowerCase()) {
  fail("manifest invoiceAdvance.paymentToken does not match paymentToken.address")
}
for (const r of ["admin", "operator", "evaluator"]) {
  if (!isAddress(manifest.roles?.[r])) fail(`manifest role ${r} is invalid`)
}
const txOf = (name) => {
  const t = manifest.transactions.find((x) => x.contractName === name)
  if (!t) fail(`manifest has no ${name} deployment transaction`)
  return t
}
const tokenTx = txOf("MockUSDC")
const iaTx = txOf("InvoiceAdvance")
if (tokenTx.contractAddress.toLowerCase() !== tokenAddr.toLowerCase()) fail("MockUSDC tx address mismatch")
if (iaTx.contractAddress.toLowerCase() !== iaAddr.toLowerCase()) fail("InvoiceAdvance tx address mismatch")
// The InvoiceAdvance constructor args carry EIP-55 checksummed addresses; they must agree with ours.
const [ctorToken, ctorAdmin, ctorOperator, ctorEvaluator] = iaTx.constructorArguments
if (checksum(tokenAddr) !== ctorToken) fail("checksummed token address != InvoiceAdvance constructor argument")
if (ctorAdmin !== manifest.roles.admin || ctorOperator !== manifest.roles.operator || ctorEvaluator !== manifest.roles.evaluator) {
  fail("manifest roles do not match InvoiceAdvance constructor arguments")
}
const symbolMatch = /^(.*?) \((\w+)\) - DEMO TOKEN/.exec(manifest.paymentToken.name ?? "")
if (!symbolMatch) fail("cannot parse token name/symbol from manifest paymentToken.name")

// ---- 3. render ----------------------------------------------------------------------------

const abiHash = (abi) => createHash("sha256").update(JSON.stringify(abi)).digest("hex")

const abiFile = (constName, artifact, contractName) =>
  HEADER(
    `ABI of ${contractName} (sha256 ${abiHash(artifact.json.abi)}).`,
    `contracts/out/${contractName}.sol/${contractName}.json`
  ) + `export const ${constName} = ${JSON.stringify(artifact.json.abi, null, 2)} as const\n`

const deploymentTs =
  HEADER(
    "Deployed addresses for XRPL EVM Testnet, taken from the deployment manifest.",
    "contracts/deployments/xrpl-evm-testnet.json"
  ) +
  `export const deployment = ${JSON.stringify(
    {
      chainId: manifest.chainId,
      network: manifest.network,
      explorer: manifest.explorer,
      sourceCommit: manifest.sourceCommit,
      contracts: {
        invoiceAdvance: {
          address: checksum(iaAddr),
          deployTxHash: iaTx.transactionHash,
          deployBlock: iaTx.blockNumber,
        },
        paymentToken: {
          address: checksum(tokenAddr),
          name: symbolMatch[1],
          symbol: symbolMatch[2],
          decimals: manifest.paymentToken.decimals,
          isDemoToken: true,
          deployTxHash: tokenTx.transactionHash,
          deployBlock: tokenTx.blockNumber,
        },
      },
      roles: manifest.roles,
    },
    null,
    2
  )} as const\n`

const indexTs =
  HEADER("Barrel for generated chain artifacts.", "contracts/script/export-abi.mjs") +
  `export { invoiceAdvanceAbi } from "./invoiceAdvanceAbi"\n` +
  `export { mockUsdcAbi } from "./mockUsdcAbi"\n` +
  `export { deployment } from "./deployment"\n`

const files = {
  "invoiceAdvanceAbi.ts": abiFile("invoiceAdvanceAbi", ia, "InvoiceAdvance"),
  "mockUsdcAbi.ts": abiFile("mockUsdcAbi", token, "MockUSDC"),
  "deployment.ts": deploymentTs,
  "index.ts": indexTs,
}

let stale = []
mkdirSync(outDir, { recursive: true })
for (const [name, src] of Object.entries(files)) {
  const formatted = await format(src)
  const p = join(outDir, name)
  const current = existsSync(p) ? readFileSync(p, "utf8") : null
  if (current !== formatted) stale.push(name)
  if (!CHECK) writeFileSync(p, formatted)
}
if (CHECK) {
  if (stale.length) fail(`stale generated files: ${stale.join(", ")} (run without --check)`)
  console.log("export-abi: generated files are up to date")
} else {
  console.log(`export-abi: wrote ${Object.keys(files).length} files to ${relative(repoRoot, outDir)}/ (${stale.length} changed)`)
}

// ---- 4. optional: compare deployed bytecode to the artifacts (read-only) -------------------

if (args.has("--verify-onchain")) {
  const rpc = process.env.XRPL_EVM_RPC_URL
  if (!rpc) fail("--verify-onchain needs XRPL_EVM_RPC_URL in the environment")
  const env = { ...process.env, ETH_RPC_URL: rpc } // via env, never argv; never printed
  const chain = run("cast", ["chain-id"], { env })
  if (Number(chain) !== EXPECTED_CHAIN_ID) fail(`RPC chain id ${chain} != ${EXPECTED_CHAIN_ID}`)

  const mask = (hex, refs) => {
    const b = Buffer.from(hex.replace(/^0x/, ""), "hex")
    for (const list of Object.values(refs ?? {})) {
      for (const { start, length } of list) b.fill(0, start, start + length)
    }
    return b.toString("hex")
  }
  for (const [label, artifact, addr] of [
    ["InvoiceAdvance", ia, iaAddr],
    ["MockUSDC", token, tokenAddr],
  ]) {
    const onchain = run("cast", ["code", addr], { env })
    const local = artifact.json.deployedBytecode
    const same =
      mask(onchain, local.immutableReferences) === mask(local.object, local.immutableReferences)
    console.log(`export-abi: ${label} deployed bytecode ${same ? "MATCHES" : "DOES NOT MATCH"} artifact (immutables masked)`)
    if (!same) process.exitCode = 1
  }
}
